mapper.select:
SELECT * FROM ( SELECT c.customer_id AS customerId, t.tenant_code AS tenantCode, c.customer_code AS customerCode, c.customer_name AS customerName, c.cust_name_abbr AS custNameAbbr, c.president_name AS presidentName, c.business_no AS businessNo, c.jurid_no AS juridNo, c.business_status_1 AS businessStatus1, c.business_item_1 AS businessItem1, c.post_code AS postCode, c.address AS address, c.telephone_no AS telephoneNo, c.facsimile_no AS facsimileNo, c.cust_memo AS custMemo, CASE WHEN c.use_at = 'Y' THEN TRUE ELSE FALSE END AS active, ROW_NUMBER() OVER (ORDER BY c.customer_code) AS rn FROM tb_customer_info c JOIN tb_tenant t ON t.tenant_id = c.tenant_id WHERE 1 = 1
AND t.tenant_code = #{tenantCode}
AND ( LOWER(c.customer_name) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(c.cust_name_abbr, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(c.president_name, '')) LIKE '%' || LOWER(#{keyword}) || '%' OR c.customer_code LIKE '%' || #{keyword} || '%' OR COALESCE(c.business_no, '') LIKE '%' || #{keyword} || '%' )
AND c.use_at = 'Y'
AND c.use_at = 'N'
) customer_query WHERE rn BETWEEN #{firstIndex} AND #{lastIndex} ORDER BY rn

SELECT u.user_id
FROM tb_user u
JOIN tb_login_account la ON la.login_id = u.login_id
WHERE la.tenant_id = #{tenantId}
  AND la.login_code = #{loginCode}
LIMIT 1

SELECT MAX(customer_code)
FROM tb_customer_info
WHERE tenant_id = #{value}

mapper.delete:
DELETE FROM tb_customer_info
WHERE customer_id = #{customerId}
  AND tenant_id   = #{tenantId}
